package com.hbm.blocks.machine.rbmk;
import com.hbm.blocks.ITooltipProvider;
import dev.golem.core.world.CompatBlock;
import net.minecraft.core.BlockPos; import net.minecraft.core.Direction; import net.minecraft.world.item.context.BlockPlaceContext; import net.minecraft.world.level.BlockGetter; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.Mirror; import net.minecraft.world.level.block.Rotation; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.level.block.state.StateDefinition; import net.minecraft.world.level.block.state.properties.BlockStateProperties; import net.minecraft.world.level.block.state.properties.EnumProperty; import net.minecraft.world.phys.shapes.CollisionContext; import net.minecraft.world.phys.shapes.VoxelShape; import org.jspecify.annotations.Nullable;
/** Three-quarter-depth wall panel; its facing names the front face. */
 public class RBMKMiniPanelBase extends CompatBlock implements ITooltipProvider { public static final EnumProperty<Direction> FACING = BlockStateProperties.HORIZONTAL_FACING; private static final VoxelShape NORTH = Block.box(0, 0, 4, 16, 16, 16), SOUTH = Block.box(0, 0, 0, 16, 16, 12), WEST = Block.box(4, 0, 0, 16, 16, 16), EAST = Block.box(0, 0, 0, 12, 16, 16); public RBMKMiniPanelBase(Properties props) { super(props); registerDefaultState(stateDefinition.any().setValue(FACING, Direction.NORTH)); } @Override protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) { builder.add(FACING); } @Override public @Nullable BlockState getStateForPlacement(BlockPlaceContext ctx) { return defaultBlockState().setValue(FACING, ctx.getHorizontalDirection().getOpposite()); } @Override public VoxelShape getShape(BlockState state, BlockGetter level, BlockPos pos, CollisionContext ctx) { return switch (state.getValue(FACING)) { case SOUTH -> SOUTH; case WEST -> WEST; case EAST -> EAST; default -> NORTH; }; } @Override public BlockState rotate(BlockState state, Rotation rotation) { return state.setValue(FACING, rotation.rotate(state.getValue(FACING))); } @Override public BlockState mirror(BlockState state, Mirror mirror) { return state.rotate(mirror.getRotation(state.getValue(FACING))); } }
